import requests

# Step 1: Gather real-time electricity demand data
realtime_demand_url = "https://api.socbench.example/realtime-demand"
response = requests.get(realtime_demand_url)
if response.status_code == 200:
    realtime_data = response.json()
else:
    raise Exception("Failed to fetch real-time demand data")

# Step 2: Analyze and adjust the power distribution strategy for specified regions
for zone in realtime_data.get("zones", []):
    zone_id = zone["zone_id"]
    demand = zone["demand"]

    # Example adjustment logic: if demand exceeds 1000 MW, adjust distribution strategy
    if demand > 1000:
        adjust_distribution_url = "https://api.socbench.example/adjust-distribution"
        new_strategy = {
            "zone_id": zone_id,
            "new_distribution_strategy": {
                "supply_limit": demand - 100,  # Reduce supply limit slightly
                "time_frame": "2023-12-31T23:59:59Z"
            }
        }
        adjust_response = requests.put(adjust_distribution_url, json=new_strategy)
        if adjust_response.status_code != 200:
            raise Exception(f"Failed to adjust distribution for zone {zone_id}")
